DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"SYS_AUDIT_LOG" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ACTOR_TYPE" NVARCHAR2(50) NOT NULL,
    "ACTOR_ID" NUMBER(19) NOT NULL,
    "COMPANY_ID" NUMBER(19),
    "BRANCH_ID" NUMBER(19),
    "ACTION" NVARCHAR2(100) NOT NULL,
    "ENTITY_TYPE" NVARCHAR2(100) NOT NULL,
    "ENTITY_ID" NUMBER(19),
    "OLD_VALUE" CLOB,
    "NEW_VALUE" CLOB,
    "IP_ADDRESS" NVARCHAR2(50),
    "USER_AGENT" NVARCHAR2(500),
    "CORRELATION_ID" NVARCHAR2(100),
    "HTTP_METHOD" NVARCHAR2(10),
    "ENDPOINT_PATH" NVARCHAR2(500),
    "REQUEST_PAYLOAD" CLOB,
    "RESPONSE_PAYLOAD" CLOB,
    "EXECUTION_TIME_MS" NUMBER(19),
    "STATUS_CODE" NUMBER(10),
    "EXCEPTION_TYPE" NVARCHAR2(200),
    "EXCEPTION_MESSAGE" NVARCHAR2(2000),
    "STACK_TRACE" CLOB,
    "SEVERITY" NVARCHAR2(20) NOT NULL,
    "EVENT_CATEGORY" NVARCHAR2(50) NOT NULL,
    "STATUS" NVARCHAR2(20),
    "METADATA" CLOB,
    "BUSINESS_MODULE" NVARCHAR2(100),
    "DEVICE_IDENTIFIER" NVARCHAR2(100),
    "ERROR_CODE" NVARCHAR2(100),
    "BUSINESS_DESCRIPTION" NVARCHAR2(500),
    "CREATION_DATE" TIMESTAMP(7) NOT NULL,
    CONSTRAINT "PK_SYS_AUDIT_LOG" PRIMARY KEY ("Id")
)';
END;
/

