    "FILE_EXTENSION" NVARCHAR2(20) NOT NULL,
    "FILE_PATH" NVARCHAR2(1000) NOT NULL,
    "DESCRIPTION" NVARCHAR2(1000),
    "CATEGORY" NVARCHAR2(50),
    "TAGS" NVARCHAR2(500),
    "OWNER_TYPE" NVARCHAR2(20) NOT NULL,
    "OWNER_ID" NUMBER(19) NOT NULL,
    "IS_ACTIVE" NVARCHAR2(1) NOT NULL,
    "CREATION_USER" NVARCHAR2(100) NOT NULL,
    "CREATION_DATE" TIMESTAMP(7),
    "UPDATE_USER" NVARCHAR2(100),
    "UPDATE_DATE" TIMESTAMP(7),
    CONSTRAINT "PK_SYS_DOCUMENT" PRIMARY KEY ("Id")
)';
END;
