                    SELECT 'print', N'طباعة', 'Print', N'Ability to print records', 'Ability to print records', NULL, 8, 1, 'seed', SYSTIMESTAMP FROM DUAL
                    WHERE NOT EXISTS (SELECT 1 FROM "SYS_FEATURE" WHERE "FEATURE_CODE" = 'print');
                    COMMIT;
                END;
