"SYS_BRANCH_SYSTEMS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "BRANCH_ID" NUMBER(19) NOT NULL,
    "SYSTEM_ID" NUMBER(19) NOT NULL,
    "GRANTED_BY" NUMBER(19),
    "GRANTED_DATE" TIMESTAMP(7),
    "REVOKED_DATE" TIMESTAMP(7),
    "NOTES" NVARCHAR2(500),
    "CREATION_USER" NVARCHAR2(100) NOT NULL,
    "CREATION_DATE" TIMESTAMP(7),
    "UPDATE_USER" NVARCHAR2(100),
    "UPDATE_DATE" TIMESTAMP(7),
    CONSTRAINT "PK_SYS_BRANCH_SYSTEMS" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SYS_BRANCH_SYSTEMS_SYS_BRANCH_BRANCH_ID" FOREIGN KEY ("BRANCH_ID") REFERENCES "SYS_BRANCH" ("Id"),
    CONSTRAINT "FK_SYS_BRANCH_SYSTEMS_SYS_SUPER_ADMIN_GRANTED_BY" FOREIGN KEY ("GRANTED_BY") REFERENCES "SYS_SUPER_ADMIN" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_SYS_BRANCH_SYSTEMS_SYS_SYSTEM_SYSTEM_ID" FOREIGN KEY ("SYSTEM_ID") REFERENCES "SYS_SYSTEM" ("Id")
)';
END;
/

